9	use std::sync::atomic::{AtomicBool, Ordering};
10	use std::sync::mpsc::{Receiver, RecvTimeoutError};
11	use std::sync::{Arc, Mutex, PoisonError};
12	use std::time::Duration;
13	
14	use rustc_hash::{FxHashMap, FxHasher};
15	
16	use super::ComponentAnswer;
17	use crate::pipeline::HtmlAttributeMode;
18	use crate::react_types::{checker_prop_used, react_props_wanted};
19	use crate::types::diagnostic::{Diagnostic, DiagnosticCode, DiagnosticSeverity};
20	use crate::types::semantic::{
21	    merge_semantic_props, SemanticComponent, SemanticOutcome, SemanticProvider, SemanticTarget,
22	};
