24	/// What the checker said about one component at one version of its file.
25	type Answers = Mutex<FxHashMap<(String, u64), Option<Arc<SemanticComponent>>>>;
26	
27	pub(crate) struct SemanticHook {
28	    provider: Arc<dyn SemanticProvider>,
29	    /// How long a request waits for the checker before it takes the structural answer.
30	    wait: Duration,
31	    answers: Arc<Answers>,
32	    /// Set once the checker has been reported unavailable, so a session says so once, not per component.
33	    warned: AtomicBool,
34	}
35	
36	impl SemanticHook {
37	    pub(crate) fn new(provider: Arc<dyn SemanticProvider>, wait: Duration) -> Self {
38	        Self { provider, wait, answers: Arc::new(Mutex::new(FxHashMap::default())), warned: AtomicBool::new(false) }
39	    }
40	
41	    /// `answer` with the checker's props, when it has them.
42	    pub(crate) fn refine(&self, mut answer: ComponentAnswer, mode: HtmlAttributeMode) -> ComponentAnswer {
43	        let stamp = std::fs::read(&answer.entry.file_path).map(|bytes| {
44	            let mut hasher = FxHasher::default();
45	            bytes.hash(&mut hasher);
46	            hasher.finish()
47	        });
48	        let cache_key = stamp.ok().map(|stamp| (answer.key.clone(), stamp));
49	
50	        if let Some(cached) = cache_key.as_ref().and_then(|key| self.cached(key)) {
51	            self.apply(&mut answer, cached.as_ref(), mode);
52	            return answer;
53	        }
54	
55	        let target = SemanticTarget {
56	            file_path: answer.entry.file_path.clone(),
57	            display_name: answer.entry.display_name.clone(),
58	            exported: answer.entry.exported,
59	            described: answer
60	                .entry
61	                .props
62	                .values()
63	                .filter(|prop| !prop.description.is_empty())
64	                .map(|prop| prop.name.clone())
65	                .collect(),
66	            react_wanted: react_props_wanted(mode, &answer.entry.props),
67	        };
68	        let receiver = self.provider.request(vec![target]);
69	        match receiver.recv_timeout(self.wait) {
70	            Ok(outcome) => {
71	                let mut reported = Vec::new();
72	                let component = self.take_component(&answer, outcome, &mut reported);
73	                answer.diagnostics.extend(reported);
74	                if let Some(key) = cache_key {
75	                    self.store(key, component.clone());
76	                }
77	                self.apply(&mut answer, component.as_ref(), mode);
78	            }
79	            Err(RecvTimeoutError::Timeout) => {
80	                self.keep_late_answer(receiver, cache_key);
81	                let mut pending = Diagnostic::new(
82	                    DiagnosticSeverity::Info,
83	                    DiagnosticCode::SemanticBackend,
84	                    "the TypeScript checker has not answered yet; the structural props are used, and the checker's \
85	                     replace them on the next request",
86	                );
87	                pending.affects = vec![answer.key.clone()];
88	                answer.diagnostics.push(pending);
89	            }
90	            Err(RecvTimeoutError::Disconnected) => {}
91	        }
