132	            diagnostics.push(diagnostic);
133	        }
134	        for fallback in fallbacks {
135	            let mut info = Diagnostic::new(
136	                DiagnosticSeverity::Info,
137	                DiagnosticCode::SemanticBackend,
138	                format!("1 component(s) kept their structural result: {}", fallback.reason),
139	            );
140	            info.affects = vec![answer.key.clone()];
141	            diagnostics.push(info);
142	        }
143	        components
144	            .into_iter()
145	            .find(|found| found.file_path == answer.entry.file_path && found.display_name == answer.entry.display_name)
146	            .map(Arc::new)
147	    }
