166	                0 => "1 component(s) resolved by the TypeScript checker".to_string(),
167	                kept => format!(
168	                    "1 component(s) resolved by the TypeScript checker; {kept} prop(s) it did not report keep their \
169	                     structural type"
170	                ),
171	            },
172	        );
173	        provenance.affects = vec![answer.key.clone()];
174	        answer.diagnostics.push(provenance);
175	    }
