1	#![allow(clippy::unwrap_used, clippy::expect_used)]
2	//! A session with a checker attached asks it for the component a request names (ADR 0022): the checker's props when it
3	//! answers in time, the structural ones when it does not, its late answer on the next request, and one warning when it
4	//! is unavailable. The checker here is a fake, so the contract is tested without `tsc`.
5	
6	use std::sync::atomic::{AtomicUsize, Ordering};
7	use std::sync::mpsc::{channel, Receiver};
8	use std::sync::Arc;
9	use std::time::Duration;
10	
11	use caliper_docgen_core::pipeline::{HtmlAttributeMode, PipelineOptions, WatchSession};
12	use caliper_docgen_core::types::semantic::{
13	    SemanticComponent, SemanticOutcome, SemanticProp, SemanticProvider, SemanticTarget,
14	};
15	use caliper_docgen_core::types::{DiagnosticCode, DiagnosticSeverity, PropType};
16	use camino::Utf8PathBuf;
17	
18	const BUTTON: &str = "export function Button(props: { label: string }) { return null; }";
19	const CARD: &str = "export function Card(props: { title: string }) { return null; }";
20	
21	/// Answers every request with `reply(target)`, after `delay`, and counts the requests.
22	struct Fake {
23	    requests: AtomicUsize,
24	    delay: Duration,
25	    reply: fn(&SemanticTarget) -> SemanticOutcome,
26	}
27	
28	impl Fake {
29	    fn new(delay: Duration, reply: fn(&SemanticTarget) -> SemanticOutcome) -> Arc<Self> {
30	        Arc::new(Self { requests: AtomicUsize::new(0), delay, reply })
31	    }
32	    fn requests(&self) -> usize {
33	        self.requests.load(Ordering::SeqCst)
34	    }
35	}
36	
37	impl SemanticProvider for Fake {
38	    fn request(&self, targets: Vec<SemanticTarget>) -> Receiver<SemanticOutcome> {
39	        self.requests.fetch_add(1, Ordering::SeqCst);
40	        let (sender, receiver) = channel();
41	        let (delay, reply) = (self.delay, self.reply);
42	        std::thread::spawn(move || {
43	            std::thread::sleep(delay);
44	            sender.send(reply(&targets[0])).ok();
45	        });
46	        receiver
47	    }
48	}
49	
50	/// The checker finds a prop the structural pass cannot see: `size`, typed as a union of two literals.
51	fn finds_size(target: &SemanticTarget) -> SemanticOutcome {
52	    let prop = |name: &str, prop_type: PropType| {
53	        Arc::new(SemanticProp {
54	            name: name.to_string(),
55	            prop_type,
56	            required: false,
57	            description: String::new(),
58	            react_declared: false,
59	        })
60	    };
61	    SemanticOutcome {
62	        components: vec![SemanticComponent {
63	            file_path: target.file_path.clone(),
64	            display_name: target.display_name.clone(),
65	            props: vec![
66	                prop("label", PropType::String),
67	                prop(
68	                    "size",
69	                    PropType::Union(vec![PropType::StringLiteral("sm".into()), PropType::StringLiteral("lg".into())]),
70	                ),
71	            ],
72	        }],
73	        ..SemanticOutcome::default()
74	    }
75	}
76	
77	/// The checker reports the component's `label` and, as `tsc` does without a filter, everything `@types/react` declares:
78	/// `children` as a string (so the checker's type is visible), `className`, `id`, and the `key` and `ref` React adds.
79	fn reports_react_props(target: &SemanticTarget) -> SemanticOutcome {
80	    let prop = |name: &str, prop_type: PropType, react_declared: bool| {
81	        Arc::new(SemanticProp {
82	            name: name.to_string(),
83	            prop_type,
84	            required: false,
85	            description: String::new(),
86	            react_declared,
87	        })
88	    };
89	    SemanticOutcome {
90	        components: vec![SemanticComponent {
91	            file_path: target.file_path.clone(),
92	            display_name: target.display_name.clone(),
93	            props: vec![
94	                prop("label", PropType::String, false),
95	                prop("children", PropType::String, true),
96	                prop("className", PropType::String, true),
97	                prop("id", PropType::String, true),
98	                prop("key", PropType::String, true),
99	                prop("ref", PropType::String, true),
100	            ],
101	        }],
102	        ..SemanticOutcome::default()
103	    }
104	}
105	
106	fn down(_: &SemanticTarget) -> SemanticOutcome {
107	    SemanticOutcome::unavailable("no tsc in this test")
108	}
109	
110	struct Project {
111	    _dir: tempfile::TempDir,
112	    root: Utf8PathBuf,
113	}
114	
115	fn project(files: &[(&str, &str)]) -> Project {
116	    let dir = tempfile::tempdir().unwrap();
117	    let root = Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
118	    for (name, source) in files {
119	        std::fs::write(root.join(name), source).unwrap();
120	    }
121	    Project { _dir: dir, root }
122	}
123	
124	fn session(project: &Project, checker: Arc<Fake>, wait: Duration) -> WatchSession {
125	    let session = WatchSession::lazy(PipelineOptions { src_dirs: vec![project.root.clone()], ..Default::default() })
126	        .with_semantic(checker, wait);
127	    let _ = session.initialize();
128	    session
129	}
130	
131	fn session_in(
132	    project: &Project,
133	    mode: HtmlAttributeMode,
134	    reply: fn(&SemanticTarget) -> SemanticOutcome,
135	) -> WatchSession {
136	    let options = PipelineOptions { src_dirs: vec![project.root.clone()], html_attributes: mode, ..Default::default() };
137	    let session = WatchSession::lazy(options).with_semantic(Fake::new(Duration::ZERO, reply), Duration::from_secs(5));
138	    let _ = session.initialize();
139	    session
140	}
141	
142	fn structural_session(project: &Project, mode: HtmlAttributeMode) -> WatchSession {
143	    let options = PipelineOptions { src_dirs: vec![project.root.clone()], html_attributes: mode, ..Default::default() };
144	    let session = WatchSession::lazy(options);
145	    let _ = session.initialize();
146	    session
147	}
148	
149	fn prop_names(session: &WatchSession, key: &str) -> Vec<String> {
150	    session.component(key).unwrap().entry.props.keys().cloned().collect()
151	}
152	
153	#[test]
154	fn a_checker_that_answers_in_time_replaces_the_structural_props_and_says_so() {
155	    let project = project(&[("Button.tsx", BUTTON)]);
156	    let checker = Fake::new(Duration::ZERO, finds_size);
157	    let session = session(&project, checker.clone(), Duration::from_secs(5));
158	
159	    let answer = session.component("Button").unwrap();
160	
161	    assert_eq!(answer.entry.props.keys().cloned().collect::<Vec<_>>(), ["label", "size"]);
162	    assert_eq!(answer.entry.props["size"].prop_type.raw_string(), "\"sm\" | \"lg\"");
163	    let provenance: Vec<_> = answer.diagnostics.iter().filter(|d| d.code == DiagnosticCode::SemanticBackend).collect();
164	    assert_eq!(provenance.len(), 1);
165	    assert_eq!(provenance[0].severity, DiagnosticSeverity::Info);
166	    assert_eq!(provenance[0].affects, ["Button"]);
167	}
168	
169	#[test]
170	fn the_checker_is_asked_once_per_version_of_the_file() {
171	    let project = project(&[("Button.tsx", BUTTON)]);
172	    let checker = Fake::new(Duration::ZERO, finds_size);
173	    let session = session(&project, checker.clone(), Duration::from_secs(5));
174	
175	    let first = session.component("Button").unwrap();
176	    let second = session.component("Button").unwrap();
177	    assert_eq!(first, second);
178	    assert_eq!(checker.requests(), 1);
179	
180	    std::fs::write(
181	        project.root.join("Button.tsx"),
182	        "export function Button(props: { label: string; tone?: string }) { return null; }",
183	    )
184	    .unwrap();
185	    session.update_file(&project.root.join("Button.tsx"));
186	    let edited = session.component("Button").unwrap();
187	
188	    assert_eq!(checker.requests(), 2, "an edited file is a new question");
189	    // The checker's fake reply does not know `tone`; the structural pass does, and a prop the checker does not return stays.
190	    assert_eq!(edited.entry.props.keys().cloned().collect::<Vec<_>>(), ["label", "size", "tone"]);
191	}
192	
193	#[test]
194	fn a_slow_checker_leaves_the_structural_props_and_its_late_answer_serves_the_next_request() {
195	    let project = project(&[("Button.tsx", BUTTON)]);
196	    let checker = Fake::new(Duration::from_millis(300), finds_size);
197	    let session = session(&project, checker.clone(), Duration::from_millis(10));
198	
199	    let early = session.component("Button").unwrap();
200	    assert_eq!(early.entry.props.keys().cloned().collect::<Vec<_>>(), ["label"]);
201	    let pending: Vec<_> = early.diagnostics.iter().filter(|d| d.code == DiagnosticCode::SemanticBackend).collect();
202	    assert_eq!(pending.len(), 1);
203	    assert!(pending[0].message.contains("has not answered yet"), "{}", pending[0].message);
204	
205	    std::thread::sleep(Duration::from_millis(900));
206	
207	    assert_eq!(prop_names(&session, "Button"), ["label", "size"]);
208	    assert_eq!(checker.requests(), 1, "the late answer was kept, not asked for again");
