300	    /// Run a full cold extraction to populate this session.
301	    ///
302	    /// Idempotent — concurrent or repeated calls return the current snapshot without re-running extraction. Use
303	    /// `rebuild` to force a fresh extraction.
304	    pub fn initialize(&self) -> ExtractionOutput {
305	        let mut writer = self.writer.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
306	        if let Some(current) = self.current.load_full() {
307	            return (*current.output).clone();
308	        }
309	        let revision = self.cold(&mut writer, 1);
310	        (*revision.output).clone()
311	    }
312	
313	    /// Discard the session's state and extract everything again.
314	    pub fn rebuild(&self) -> ExtractionOutput {
315	        let mut writer = self.writer.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
316	        let id = self.current.load().as_ref().map_or(1, |r| r.id + 1);
317	        let revision = self.cold(&mut writer, id);
318	        (*revision.output).clone()
319	    }
320	
321	    /// Extract everything as revision `id` and publish it. The caller holds the writer lock.
322	    fn cold(&self, writer: &mut Freshness, id: u64) -> Arc<Revision> {
323	        *writer = Freshness::cold(SystemTime::now());
324	        let revision = Arc::new(match self.lazy {
325	            true => Revision::cold_lazy(&self.options, id),
326	            false => Revision::cold(&self.options, id),
327	        });
328	        self.current.store(Some(revision.clone()));
329	        revision
330	    }
