332	    /// The published revision's number: 0 before `initialize`, then one higher for every change that produced a new
333	    /// revision. An update that leaves it unchanged changed nothing.
334	    pub fn revision(&self) -> u64 {
335	        self.current.load().as_ref().map_or(0, |revision| revision.id)
336	    }
