use caliper_docgen_core::pipeline::PipelineOptions;
use camino::Utf8PathBuf;

#[test]
fn probe() {
    let sources = [
        "export function Button<T>(props: { label: string; item: T extends string ? 1 : 2 }) { return null; }",
        "type M<T> = { [K in keyof T]: T[K] };\nexport function Button<T>(props: { label: string; extra: M<T> }) { return null; }",
        "type U<T> = T extends Promise<infer R> ? R : T;\nexport function Button<T>(props: { label: string; item: U<T> }) { return null; }",
    ];
    for source in sources {
        let dir = tempfile::tempdir().unwrap();
        let root = Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
        std::fs::write(root.join("Button.tsx"), source).unwrap();
        let out = caliper_docgen_core::extract(&PipelineOptions { src_dirs: vec![root], ..Default::default() });
        let entry = &out.components["Button"];
        for (name, prop) in &entry.props {
            println!("PROP {name} opaque={} raw={}", prop.prop_type.raw_string().contains("opaque"), prop.prop_type.raw_string());
        }
        for d in &out.diagnostics {
            println!("DIAG {:?} {:?} affects={:?}", d.code, d.severity, d.affects);
        }
        println!("-----");
    }
}

