    let cwd = TempDir::new().unwrap();
    let output = Command::new(env!("CARGO_BIN_EXE_caliper-docgen"))
        .current_dir(cwd.path())
        .args(["--quiet", "extract", "--out", "out.json", "--src", src.path().to_str().unwrap()])
        .output()
        .expect("failed to spawn the real binary");

